  Theorem drv_openA : forall KA KF R (model : Model) (tid : word),
    let vals := vals_mainA sp0 p0 p1 can tid R in
    regs_ok (ENVA vals) sr_mainA R -> know_ok ASEGS (ENVA vals) (mrestrict (ahid A0 model) M0) kn_mainA ->
